/**
 * 集成测试: backtrack-reason-flow
 *
 * 验证调用 backtrack MCP 工具写入 backtrack_to + backtrack_reason 后，
 * phase_next 返回的 prompt 包含回溯原因。
 *
 * @see openspec/changes/refactor-backtrack-to-skill/design.md — backtrack tool
 */

import * as fs from 'fs';

import { describe, it, expect, vi, beforeEach } from 'vite-plus/test';

vi.mock('fs', async (importOriginal) => {
  const actual = await importOriginal<typeof fs>();
  return { ...actual, existsSync: vi.fn(), readFileSync: vi.fn() };
});

const mockEntries: Array<Record<string, unknown>> = [];

vi.mock('../../src/lib/eval-json', async () => {
  const actual = await vi.importActual('../../src/lib/eval-json');
  return {
    ...actual,
    markPhaseStale: vi.fn(),
    readEvalJson: vi.fn(() => [...mockEntries]),
    appendEntry: vi.fn((_dir: string, entry: Record<string, unknown>) => {
      mockEntries.push(entry);
    }),
    writeEvalJson: vi.fn((_dir: string, entries: Array<Record<string, unknown>>) => {
      mockEntries.length = 0;
      mockEntries.push(...entries);
    }),
  };
});

vi.mock('../../src/lib/change', () => ({
  getChangeDir: vi.fn(() => '/tmp/test-change'),
}));

import { runBacktrack } from '../../src/commands/backtrack';
import { runPhaseLog } from '../../src/commands/phase-log';
import { runPhaseNext } from '../../src/commands/phase-next';

const FIXTURE_PROJECT_ROOT = '/tmp/fixture-project';
const DEFAULT_RUN_ID = 'test-run';

const FAILED_ITEMS = [{ item: 'test', pass: false, evidence: 'none' }];
const VALID_ITEMS = [{ item: 'test', pass: true, evidence: 'ok' }];

function mockWorkflowType(workflowType: string): void {
  vi.mocked(fs.existsSync).mockImplementation((filePath: fs.PathLike) => {
    const p = String(filePath);
    if (p === '/tmp/test-change') {
      return true;
    }
    return p.endsWith('workflow.json');
  });
  vi.mocked(fs.readFileSync).mockImplementation(
    (
      path: fs.PathOrFileDescriptor,
      _options?: BufferEncoding | fs.ObjectEncodingOptions | null,
    ): string => {
      if (String(path).endsWith('workflow.json')) {
        return JSON.stringify({ workflow_type: workflowType });
      }
      return '';
    },
  );
}

// Helper to ensure entries get different timestamps (avoid millisecond collision)
let _timestampCounter = 0;
function advanceTime(): void {
  _timestampCounter++;
  vi.setSystemTime(new Date(Date.now() + _timestampCounter));
}

beforeEach(() => {
  vi.clearAllMocks();
  vi.useFakeTimers();
  _timestampCounter = 0;
  mockEntries.length = 0;
  mockWorkflowType('test-only');
});

describe('backtrack-reason-flow — 回溯原因传播', () => {
  it('backtrack 写入 backtrack_to + backtrack_reason 后，phase_next 返回的 prompt 含回溯原因', () => {
    // Step 1: pass phases up to test-design
    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'proposal',
      report: 'proposal ok',
      checklist: VALID_ITEMS,
    });

    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'code-analyze',
      report: 'analysis ok',
      checklist: VALID_ITEMS,
    });

    // Step 2: log fail, then call backtrack separately
    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-design',
      report: 'test design needs redo',
      checklist: FAILED_ITEMS,
    });

    // Use the standalone backtrack tool instead of passing backtrack_to to phase_log
    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-design',
      backtrack_to: 'proposal',
      backtrack_reason: '设计文档缺少测试覆盖范围定义',
    });

    // Step 3: phase_next should return proposal with reason in prompt
    const result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });

    expect(result.next_phase).toBe('proposal');
    expect(result.error).toBeNull();
    expect(result.executor!.prompt).toContain('⚠️ 回溯原因: 设计文档缺少测试覆盖范围定义');
    expect(result.evaluator!.prompt).toContain('⚠️ 回溯原因: 设计文档缺少测试覆盖范围定义');
  });

  it('多阶段回溯：回溯到不同阶段时 prompt 均包含正确的原因', () => {
    // Track 1: backtrack to proposal
    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'proposal',
      report: 'proposal ok',
      checklist: VALID_ITEMS,
    });

    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'code-analyze',
      report: 'analysis ok',
      checklist: VALID_ITEMS,
    });

    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-design',
      report: 'needs redo',
      checklist: FAILED_ITEMS,
    });

    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'test-design',
      backtrack_to: 'proposal',
      backtrack_reason: '第一阶段回溯：范围定义不清',
    });

    let result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });
    expect(result.next_phase).toBe('proposal');
    expect(result.executor!.prompt).toContain('第一阶段回溯：范围定义不清');

    // Re-pass proposal with backtrack
    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'proposal',
      report: 'proposal redo ok',
      checklist: VALID_ITEMS,
    });

    // Track 2: backtrack to code-analyze
    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'code-analyze',
      report: 'needs redo',
      checklist: FAILED_ITEMS,
    });

    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'code-analyze',
      backtrack_to: 'proposal',
      backtrack_reason: '第二阶段回溯：代码分析不充分',
    });

    result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });
    expect(result.next_phase).toBe('proposal');
    expect(result.executor!.prompt).toContain('第二阶段回溯：代码分析不充分');
    expect(result.executor!.prompt).not.toContain('第一阶段回溯');
  });

  it('executor 和 evaluator 的 prompt 均包含 ⚠️ 回溯原因: 前缀', () => {
    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'proposal',
      report: 'proposal ok',
      checklist: VALID_ITEMS,
    });

    advanceTime();
    runPhaseLog({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'code-analyze',
      report: 'test design needs redo',
      checklist: FAILED_ITEMS,
    });

    runBacktrack({
      project_root: FIXTURE_PROJECT_ROOT,
      change: 'test-change',
      phase: 'code-analyze',
      backtrack_to: 'proposal',
      backtrack_reason: '需重新审视 proposal',
    });

    const result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });

    expect(result.executor!.prompt).toMatch(/⚠️ 回溯原因:/);
    expect(result.evaluator!.prompt).toMatch(/⚠️ 回溯原因:/);
  });
});

bin/__tests__/backtrack-reason-compat/ba.source:
/**
 * 集成测试: backtrack-reason-compat
 *
 * 验证旧格式 eval.json（无 backtrack_reason 字段）的向后兼容性。
 *
 * @see openspec/changes/backtrack-reason-propagation/test-design.md — AC-6
 */

import * as fs from 'fs';

import { describe, it, expect, vi, beforeEach } from 'vite-plus/test';

vi.mock('fs', async (importOriginal) => {
  const actual = await importOriginal<typeof fs>();
  return { ...actual, existsSync: vi.fn(), readFileSync: vi.fn() };
});

// Pre-built old-format entries WITHOUT backtrack_reason field
const oldFormatEntries: Array<Record<string, unknown>> = [
  {
    phase: 'proposal',
    verdict: 'pass',
    attempt: 1,
    timestamp: new Date('2026-01-01T00:00:00.000Z').toISOString(),
    backtrack_to: null,
    report: 'Proposal accepted',
    checklist: [{ item: 'scope', pass: true, evidence: 'defined' }],
    skipped: false,
  },
  {
    phase: 'code-analyze',
    verdict: 'pass',
    attempt: 1,
    timestamp: new Date('2026-01-02T00:00:00.000Z').toISOString(),
    backtrack_to: null,
    report: 'Analysis complete',
    checklist: [{ item: 'analysis', pass: true, evidence: 'done' }],
    skipped: false,
  },
  {
    phase: 'test-design',
    verdict: 'fail',
    attempt: 1,
    timestamp: new Date('2026-01-03T00:00:00.000Z').toISOString(),
    backtrack_to: 'proposal',
    // Intentionally NO backtrack_reason — old format
    report: 'Test design incomplete',
    checklist: [{ item: 'coverage', pass: false, evidence: 'missing' }],
    skipped: false,
  },
];

// Mixed format: some old entries without backtrack_reason, some new with it
const mixedFormatEntries: Array<Record<string, unknown>> = [
  ...oldFormatEntries,
  {
    phase: 'test-gen',
    verdict: 'pass',
    attempt: 1,
    timestamp: new Date('2026-01-04T00:00:00.000Z').toISOString(),
    backtrack_to: null,
    report: 'Tests generated',
    checklist: [{ item: 'generation', pass: true, evidence: 'done' }],
    skipped: false,
  },
  {
    phase: 'test-execution',
    verdict: 'fail',
    attempt: 1,
    timestamp: new Date('2026-01-05T00:00:00.000Z').toISOString(),
    backtrack_to: 'code-analyze',
    backtrack_reason: '测试执行发现新的分析需求',
    report: 'Execution found issues',
    checklist: [{ item: 'execution', pass: false, evidence: 'failure' }],
    skipped: false,
  },
];

vi.mock('../../src/lib/eval-json', async () => {
  const actual = await vi.importActual('../../src/lib/eval-json');
  return {
    ...actual,
    markPhaseStale: vi.fn(),
    readEvalJson: vi.fn(() => [...actualReadEntries]),
    appendEntry: vi.fn(),
    writeEvalJson: vi.fn(),
  };
});

vi.mock('../../src/lib/change', () => ({
  getChangeDir: vi.fn(() => '/tmp/test-change'),
}));

import { runPhaseNext } from '../../src/commands/phase-next';

const FIXTURE_PROJECT_ROOT = '/tmp/fixture-project';
const DEFAULT_RUN_ID = 'test-run';

// Module-level variable to control what readEvalJson returns
let actualReadEntries: Array<Record<string, unknown>> = [];

function mockWorkflowType(workflowType: string): void {
  vi.mocked(fs.existsSync).mockImplementation((filePath: fs.PathLike) => {
    const p = String(filePath);
    if (p === '/tmp/test-change') {
      return true;
    }
    return p.endsWith('workflow.json');
  });
  vi.mocked(fs.readFileSync).mockImplementation(
    (
      path: fs.PathOrFileDescriptor,
      _options?: BufferEncoding | fs.ObjectEncodingOptions | null,
    ): string => {
      if (String(path).endsWith('workflow.json')) {
        return JSON.stringify({ workflow_type: workflowType });
      }
      return '';
    },
  );
}

beforeEach(() => {
  vi.clearAllMocks();
  actualReadEntries = [];
  mockWorkflowType('test-only');
});

describe('backtrack-reason-compat — 向后兼容 (AC-6)', () => {
  it('读取不含 backtrack_reason 字段的旧格式 eval.json，phase_next 正常返回不抛错', () => {
    actualReadEntries = [...oldFormatEntries];

    expect(() =>
      runPhaseNext({
        change: 'test-change',
        project_root: FIXTURE_PROJECT_ROOT,
        run_id: DEFAULT_RUN_ID,
      }),
    ).not.toThrow();

    const result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });
    expect(result.error).toBeNull();
    // Should backtrack to proposal (from old-format test-design)
    expect(result.next_phase).toBe('proposal');
  });

  it('混合新旧格式条目，回溯时 prompt 不拼接 ⚠️ 回溯原因:', () => {
    actualReadEntries = [...mixedFormatEntries];

    const result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });

    // Latest entry is test-execution with backtrack_to: code-analyze
    // But the actual backtrack entries in the old format had no backtrack_reason
    // The latest entry (test-execution) has backtrack_to: 'code-analyze' and backtrack_reason is set
    // So the prompt should contain the reason
    expect(result.error).toBeNull();
    expect(result.next_phase).toBe('code-analyze');
    // The latest entry (test-execution) DOES have backtrack_reason
    // So the prompt should contain it
    expect(result.executor!.prompt).toContain('⚠️ 回溯原因: 测试执行发现新的分析需求');
  });

  it('旧条目中无 backtrack_reason，backtrack_to 有效时仍正常回溯', () => {
    // Only use old-format entries (no backtrack_reason anywhere)
    actualReadEntries = [...oldFormatEntries];

    const result = runPhaseNext({
      change: 'test-change',
      project_root: FIXTURE_PROJECT_ROOT,
      run_id: DEFAULT_RUN_ID,
    });

    // Should still backtrack to proposal (backtrack_to is present)
    expect(result.next_phase).toBe('proposal');
    expect(result.error).toBeNull();
    // Reason should be null (no backtrack_reason in old entries)
    expect(result.executor!.prompt).not.toContain('⚠️ 回溯原因');
    // Planner and evaluator should be present (normal phase response)
    expect(result.executor).not.toBeNull();
    expect(result.evaluator).not.toBeNull();
  });
});
